sequenceDiagram(name = "Collision Risk Assessment") {
    val camera = lifeline(name = "Camera Sensor")
    val radar = lifeline(name = "Radar Sensor")
    val fusionUnit = lifeline(name = "Fusion Unit")
    val brakingAssistant = lifeline(name = "Emergency Braking Assistant")
    val driver = lifeline(name = "Driver") { isActor = true }
    val controlUnit = lifeline(name = "Control Unit")
    val diagnosticLog = lifeline(name = "Diagnostic Log")

    message(from = camera, to = fusionUnit, label = "deliverMeasurementData()")
    message(from = radar, to = fusionUnit, label = "deliverMeasurementData()")
    message(from = fusionUnit, to = brakingAssistant, label = "computeEnvironmentModel()")
    reply(from = brakingAssistant, to = fusionUnit, label = "collisionRisk(timeToCollision)")

    alt {
        branch(guard = "[timeToCollision < criticalThreshold]") {
            message(from = brakingAssistant, to = driver, label = "warnAcoustically()")
            message(from = brakingAssistant, to = controlUnit, label = "initiateBrakingManeuver()")
            loop(guard = "[!vehicleStationary]") {
                message(from = brakingAssistant, to = controlUnit, label = "adjustBrakePressure()")
            }
            message(from = brakingAssistant, to = controlUnit, label = "endManeuver()")
            message(from = brakingAssistant, to = diagnosticLog, label = "recordEvent()")
        }
        branch(guard = "[timeToCollision >= criticalThreshold]") {
            message(from = brakingAssistant, to = driver, label = "showDistanceWarning()")
            message(from = brakingAssistant, to = diagnosticLog, label = "logObservedRisk()")
        }
    }
}

